foreach(['Data i godzina','IP','Zdarzenie','Login','Geolokalizacja i mapa','Przeglądarka / system','Ekran / okno','Kolory','Ciasteczka','Java','Język','DPR'] as $label)echo '<th>'.h($label).'</th>';echo '</tr></thead><tbody>';
